const body = $json.body || {};
const customer = body.customer || {};
const items = body.items || [];
const couponCode = (body.couponCode || '').trim().toUpperCase();

if (!customer.name || !customer.email) {
  return [{
    json: {
      statusCode: 400,
      response: { success: false, message: '請填寫完整的訂購人姓名與電子信箱！' }
    }
  }];
}

if (!items || items.length === 0) {
  return [{
    json: {
      statusCode: 400,
      response: { success: false, message: '購物車內無有效商品！' }
    }
  }];
}

// 後端真實價格對應表 (防前端金額竄改)
const priceBook = {
  'prod_1': { name: 'n8n 企業自動化私有化部署', price: 45000 },
  'prod_2': { name: 'AI 向量知識庫 (RAG) 模組', price: 25000 }
};

let subtotal = 0;
const verifiedItems = [];

for (const item of items) {
  const product = priceBook[item.id];
  if (product && item.qty > 0) {
    const itemTotal = product.price * item.qty;
    subtotal += itemTotal;
    verifiedItems.push({
      id: item.id,
      name: product.name,
      unitPrice: product.price,
      qty: item.qty,
      subtotal: itemTotal
    });
  }
}

// 優惠代碼折扣計算
let discountAmount = 0;
let discountReason = '無套用優惠券';

if (couponCode === 'VIP88') {
  discountAmount = Math.round(subtotal * 0.12); // 88 折 (折抵 12%)
  discountReason = 'VIP 尊榮 88 折優惠 (省下 12%)';
} else if (couponCode === 'SAVE500') {
  discountAmount = 500;
  discountReason = '滿額折抵現折 $500 元';
} else if (couponCode === 'WELCOME') {
  discountAmount = 200;
  discountReason = '新會員迎賓折抵 $200 元';
} else if (couponCode !== '') {
  discountReason = '無效或已過期的優惠代碼';
}

const discountedSubtotal = Math.max(0, subtotal - discountAmount);
const tax = Math.round(discountedSubtotal * 0.05);
const grandTotal = discountedSubtotal + tax;
const orderNumber = 'ORD-' + new Date().getFullYear() + '-' + Math.floor(100000 + Math.random() * 900000);

return [{
  json: {
    statusCode: 200,
    response: {
      success: true,
      message: '訂單已成功建立並完成結帳！',
      orderNumber: orderNumber,
      customer: customer,
      receipt: {
        subtotal: subtotal,
        discountAmount: discountAmount,
        discountReason: discountReason,
        discountedSubtotal: discountedSubtotal,
        tax: tax,
        grandTotal: grandTotal,
        items: verifiedItems
      }
    }
  }
}];
